// Logo oficial da Casa Brazil — vetores extraídos do PDF oficial
// (logo-casa-brazil.pdf) sem redesenho. Três variantes: símbolo, empilhada e
// horizontal. A cor vem de `currentColor`, então cada uso escolhe o tom da
// paleta via CSS. Gerado por scripts/logo-from-pdf.py — não editar à mão.

type LogoProps = {
  className?: string;
  /** Texto acessível. Passe "" quando o logo for decorativo ao lado de texto. */
  title?: string;
};

function a11y(title: string) {
  return title ? { role: "img", "aria-label": title } : { "aria-hidden": true as const };
}

